{"command": "mkdir -p /tmp/an && cat > /tmp/an/insp.py <<'PYEOF'
import sys, struct

def parse_frame(data, off=0, verbose=True):
    magic = struct.unpack_from('<I', data, off)[0]
    if magic == 0x184D2A5E:
        sz = struct.unpack_from('<I', data, off+4)[0]
        print("SKIP frame at %d size %d" % (off, sz))
        return off+8+sz
    if magic != 0xFD2FB528:
        print("no magic at %d: %x" % (off, magic)); return None
    d = data[off+4]
    fcsFlag=(d>>6)&3; single=(d>>5)&1; chk=(d>>2)&1; dic=(d>>1)&1
    p = off+5
    win=None
    if not single:
        w=data[p]; exp=w>>3; man=w&7
        if exp: wl=10+exp; ws=(1<<wl)+(man*(1<<wl)//8)
        else: ws=1024
        win=ws; p+=1
    if fcsFlag==0:
        if single:
            fcs=data[p]; p+=1
        else: fcs=None
    elif fcsFlag==1:
        fcs=struct.unpack_from('<H',data,p)[0]+256; p+=2
    elif fcsFlag==2:
        fcs=struct.unpack_from('<I',data,p)[0]; p+=4
    else:
        fcs=struct.unpack_from('<Q',data,p)[0]; p+=8
    dictid=None
    if dic:
        dictid=struct.unpack_from('<I',data,p)[0]; p+=4
    if verbose:
        print("frame@%d desc=%02x fcsFlag=%d single=%d chk=%d dict=%d win=%s fcs=%s dictid=%s" % (off,d,fcsFlag,single,chk,dic,win,fcs,dictid))
    # blocks
    nblk=0
    while True:
        if p+3>len(data): print("  ...ran out of data at %d"%p); return None
        h=data[p]|(data[p+1]<<8)|(data[p+2]<<16); p+=3
        last=h&1; typ=(h>>1)&3; size=h>>3
        body=data[p:p+size]; p+=size
        nblk+=1
