    else if(v<=1.0) snprintf(num,sizeof num,"%.3f",v);
    else if(v<10.0) snprintf(num,sizeof num,"%.2f",v);
    else if(v<100.0) snprintf(num,sizeof num,"%.1f",v);
    else snprintf(num,sizeof num,"%.0f",v);
    if(numw>0) snprintf(out,48,"%*s %s",numw,num,unit);
    else snprintf(out,48,"%s %s",num,unit);
    return (int)strlen(out);
}

static void usage_short(void){
    fputs("Compress or decompress the INPUT file(s); reads from STDIN if INPUT is `-` or not provided.\n\n"
          "Usage: executable [OPTIONS...] [INPUT... | -] [-o OUTPUT]\n\n"
          "Options:\n",stdout);
}

int main(int argc,char**argv){
    int mode=0 /*0 compress, 1 decompress*/;
    int level=3, verbose=0, quiet=0, force=0, keep=1, rmFlag=0, toStdout=0;
    int ultra=0, listMode=0, testMode=0;
    const char*output=NULL;
    int i,filesStart=-1; int nargs=0;
    /* first pass: options */
    for(i=1;i<argc;i++){
        const char*a=argv[i];
        if(a[0]!='-'||a[1]==0){ nargs++; continue; }
        if(!strcmp(a,"--")){ break; }
        if(!strcmp(a,"-d")||!strcmp(a,"--decompress")) mode=1;
        else if(!strcmp(a,"-c")||!strcmp(a,"--stdout")) toStdout=1;
        else if(!strcmp(a,"-k")||!strcmp(a,"--keep")) keep=1;
        else if(!strcmp(a,"--rm")) rmFlag=1;
        else if(!strcmp(a,"-f")||!strcmp(a,"--force")) force=1;
        else if(!strcmp(a,"-v")) verbose++;
        else if(!strcmp(a,"-q")) quiet++;
        else if(!strcmp(a,"-V")||!strcmp(a,"--version")){ fputs("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n",stdout); return 0; }
        else if(!strcmp(a,"-H")||!strcmp(a,"--help")){ usage_short(); return 0; }
        else if(a[1]=='h'){ usage_short(); return 0; }
        else if(!strcmp(a,"-l")) listMode=1;
        else if(!strcmp(a,"--test")) testMode=1;
        else if(a[1]>='1'&&a[1]<='9'){ level=atoi(a+1); }
        else if(!strncmp(a,"-o",2)){ if(!a[2]){ if(i+1>=argc){ fputs("error: missing command argument \n",stderr); return 1;} output=argv[++i]; } else output=a+2; }
        else if(!strncmp(a,"--fast",6)||!strcmp(a,"--ultra")){ if(!strcmp(a,"--ultra")) ultra=1; }
        else if(!strncmp(a,"--long",6)){}
        else { /* unknown */
            fprintf(stderr,"Incorrect parameter: %s \n",a);
            usage_short(); return 1;
        }
    }
    if(verbose>=1) fputs("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n",stderr);
    if(listMode){ fputs("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n",stdout); return 0; }
    (void)ultra;(void)level;
    int nfiles=0; const char**files=(const char**)malloc(sizeof(char*)*(nargs+2));
    int start=(filesStart<0)?1:1;
    for(i=1;i<argc;i++){
        const char*a=argv[i];
        if(!strcmp(a,"--")) continue;
        if(a[0]=='-'&&a[1]&&strcmp(a,"-")!=0){
            if(!strncmp(a,"-o",2)&&a[2]) continue;
            if(!strcmp(a,"-o")){ i++; continue; }
            continue;
        }
        files[nfiles++]=a;
    }
    (void)start;
    if(nfiles==0){ files[nfiles++]="-"; }
    int exitCode=0;
    for(i=0;i<nfiles;i++){
        const char*in=files[i];
        FILE*f;
        if(!strcmp(in,"-")) f=stdin;
        else { f=fopen(in,"rb"); if(!f){ fprintf(stderr,"zstd: can't stat %s : %s -- ignored \n",in,strerror(errno)); exitCode=1; continue; } }
        FILE*o;
        const char*on="-";
        if(toStdout) on="-";
        else if(output) on=output;
        else {
            static char buf[4096]; snprintf(buf,sizeof buf,"%s.zst",in); on=buf;
        }
        if(!strcmp(on,"-")) o=stdout;
        else { o=fopen(on,"wb"); if(!o){ fprintf(stderr,"zstd: cannot open %s\n",on); exitCode=1; if(f!=stdin) fclose(f); continue; } }
        if(!mode){
            /* read whole file */
            fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
            unsigned char*src=(unsigned char*)malloc(sz?sz:1);
            if(sz) { if(fread(src,1,sz,f)!=(size_t)sz){} }
            size_t before=(size_t)sz;
            write_frame(o,src,before,1);
            size_t after=(size_t)ftell(o);
            if(o!=stdout) fclose(o);
            double ratio=before?100.0*(double)after/(double)before:0.0;
            char s1[48],s2[48]; fmt_size(s1,before,6); fmt_size(s2,after,7);
            fprintf(stderr,"%20s: %6.2f%%   (%s => %s, %s) \n",in,ratio,s1,s2,on);
            free(src);
        } else {
            size_t written=0; int r;
            while((r=read_frame(f,o,&written))==1){ }
            if(o!=stdout) fclose(o);
            if(r!=0&&r!=1){
                fprintf(stderr,"%s : %s \n",in,(r==-36)?"Decoding error (36) : Restored data doesn't match checksum":
                        (r==-3)?"Decoding error (52) : compressed block not implemented":
                        "Read error (39) : premature end");
                exitCode=1;
            } else {
                fprintf(stderr,"%20s: %lu bytes \n",in,(unsigned long)written);
            }
        }
        if(f!=stdin) fclose(f);
    }
    free(files);
    return exitCode;
}
